use verus::prelude::*;

verus! {
    /// Find an index of a minimum element in a[from..to).
    /// Requires 0 <= from < to <= a.len().
    /// Ensures the slice is unchanged, the result lies in [from, to),
    /// and that for all k in [from, to), a@[result] <= a@[k].
    pub fn find_min(a: &mut [i32], from: usize, to: usize) -> (min_idx: usize)
        requires
            from < to,
            to <= a.len(),
        ensures
            // result in range
            from <= min_idx && min_idx < to,
        ensures
            // slice is unchanged
            a@ == old(a@),
        ensures
            // a@[min_idx] is minimal on [from, to)
            forall |k: usize| (from <= k && k < to) ==> a@[min_idx] <= a@[k],
    {
        // Initialize i to scan elements from from+1 up to to-1.
        let mut i: usize = from + 1;
        // curr_min is our current best index, starting at `from`.
        let mut curr_min: usize = from;

        // Loop over i in [from+1, to)
        while i < to
            invariant
                // i always stays in [from+1, to]
                from + 1 <= i && i <= to,
            invariant
                // curr_min is in [from, i)
                from <= curr_min && curr_min < i,
            invariant
                // curr_min is indeed the minimal index over [from, i)
                forall |k: usize| (from <= k && k < i) ==> a@[curr_min] <= a@[k],
            decreases
                // measure decreases strictly each iteration
                to - i,
        {
            // If we find a strictly smaller element at i, update curr_min.
            if a[i] < a[curr_min] {
                curr_min = i;
            } else {
                // Otherwise we know a[curr_min] <= a[i], which
                // is needed to extend the invariant to i+1.
                assert(a[curr_min] <= a[i]);
            }
            i += 1;
        }

        curr_min
    }
}